def normalize_phone(raw):
    if not raw:
        return ""
    s = "".join([c for c in str(raw) if c.isdigit()])
    if s.startswith("00"):
        s = s[2:]
    if s.startswith("0"):
        s = "966" + s[1:]
    if not s.startswith("966") and len(s) <= 10:
        if len(s) == 10 and s.startswith("05"):
            s = "966" + s[1:]
        elif len(s) == 9:
            s = "966" + s
        elif len(s) == 10 and s.startswith("5"):
            s = "966" + s
    return s

