OLD_LANDLINE = "966163274444"


def _load_db_raw():
    if not os.path.exists(DB_FILE):
        return json.loads(json.dumps(DEFAULT, ensure_ascii=False))
    try:
        with open(DB_FILE, encoding="utf-8") as fh:
            d = json.load(fh)
        for k in DEFAULT:
            if k not in d:
                d[k] = json.loads(json.dumps(DEFAULT[k], ensure_ascii=False))
        # ترحيل الشريط القديم: الرقم الثابت يتحول إلى متغيرات تتحدث تلقائياً
        m = d.get("marquee_text", "")
        if "{PHONE}" not in m and "{LANDLINE}" not in m and OLD_LANDLINE in m:
            d["marquee_text"] = m.replace(OLD_LANDLINE, "{LANDLINE} - {PHONE}", 1)
        for key, tok in (("main_phone", "{PHONE}"), ("landline", "{LANDLINE}")):
            v = d.get(key, "")
            m = d.get("marquee_text", "")
            if v and tok not in m and v in m:
                d["marquee_text"] = m.replace(v, tok)
        return d
    except Exception:
        return json.loads(json.dumps(DEFAULT, ensure_ascii=False))

