def _repair_hours(d):
    """إصلاح بيانات الدوام القديمة الخاطئة (الدوام الثاني كان نسخة من الصباحي): نرجعها من قالب الإكسل."""
    for b in d.get("branches", []):
        t = TEMPLATE_HOURS.get(" ".join(str(b.get("name", "")).split()))
        h1 = " ".join(str(b.get("hours1", "")).split())
        h2 = " ".join(str(b.get("hours2", "")).split())
        # علامة البيانات القديمة الخاطئة: الدوام الثاني نسخة من الأول أو يبدأ من 8 صباحا
        if t and (h1 == h2 or h2.startswith("من 8 صباحا")):
            b["hours1"], b["hours2"], b["friday"] = t
    return d


def load_db():
    return _repair_hours(_load_db_raw())

