        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(db, fh, ensure_ascii=False, indent=2)
        os.replace(tmp, DB_FILE)      # كتابة آمنة: لا يتلف الملف لو توقف البرنامج أثناء الحفظ

