SA_TZ = timezone(timedelta(hours=3))          # السعودية UTC+3 بدون توقيت صيفي
GREETING = "السلام عليكم ورحمة الله وبركاته. احتاج أسأل عن "
AR_DAYS = ["الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت", "الأحد"]


def now_sa():
    return datetime.now(SA_TZ)


def when_ar(r):
    """«يوم الأحد 2026-11-01 الساعة 10:45 م» من حقل date المخزّن"""
    ds = str(r.get("date", ""))
    try:
        dt = datetime.strptime(ds, "%Y-%m-%d %H:%M")
    except ValueError:
        return ds
    h = dt.hour % 12 or 12
    return f"يوم {AR_DAYS[dt.weekday()]} {dt.strftime('%Y-%m-%d')} الساعة {h}:{dt.minute:02d} {'ص' if dt.hour < 12 else 'م'}"


UPLOAD_DIR = os.path.join(os.path.dirname(os.path.abspath(DB_FILE)), "uploads")
UP_RE = re.compile(r"^[a-f0-9]{24}\.(jpg|webm|ogg|m4a|wav|mp3)$")
UP_MIME = {"jpg": "image/jpeg", "webm": "audio/webm", "ogg": "audio/ogg", "m4a": "audio/mp4", "wav": "audio/wav", "mp3": "audio/mpeg"}
UP_MAX_BYTES = 4 * 1024 * 1024
UP_MAX_AGE = 30 * 86400
UP_MAX_FILES = 3000
_UP_HITS = {}


def _sniff_audio(b):
    if b[:4] == bytes.fromhex("1a45dfa3"):
        return "webm"
    if b[:4] == b"OggS":
        return "ogg"
    if b[4:8] == b"ftyp":
        return "m4a"
    if b[:4] == b"RIFF" and b[8:12] == b"WAVE":
        return "wav"
    if b[:3] == b"ID3" or (len(b) > 1 and b[0] == 0xFF and (b[1] & 0xE0) == 0xE0):
        return "mp3"
    return None


def _up_rate_ok(ip, limit=40, window=600):
    t = time.time()
    hits = [x for x in _UP_HITS.get(ip, []) if t - x < window]
    if len(hits) >= limit:
        _UP_HITS[ip] = hits
        return False
    hits.append(t)
    _UP_HITS[ip] = hits
    if len(_UP_HITS) > 5000:
        _UP_HITS.clear()
    return True


def _prune_uploads():
    try:
        paths = [os.path.join(UPLOAD_DIR, n) for n in os.listdir(UPLOAD_DIR)]
        now = time.time()
        keep = []
        for p in paths:
            if now - os.path.getmtime(p) > UP_MAX_AGE:
                os.remove(p)
            else:
                keep.append(p)
        if len(keep) > UP_MAX_FILES:
            keep.sort(key=os.path.getmtime)
            for p in keep[:len(keep) - UP_MAX_FILES]:
                os.remove(p)
    except OSError:
        pass
