HTML_TEMPLATE = HTML_TEMPLATE.replace("__LOGO__", LOGO_B64).replace("__QR__", QR_B64 or LOGO_B64)

def render_marquee(db):
    t = html.escape(db.get("marquee_text", DEFAULT["marquee_text"]))
    return t.replace("{PHONE}", db.get("main_phone", "")).replace("{LANDLINE}", db.get("landline", ""))

@app.route("/")
def home():
    db = load_db()
    main_phone = db.get("main_phone", "966536405559")
    h = HTML_TEMPLATE
    h = h.replace("__MARQUEE__", render_marquee(db))
    h = h.replace("__GREET__", urllib.parse.quote(GREETING))
    h = h.replace("__MAIN_PHONE__", html.escape(main_phone))
    h = h.replace("__LANDLINE__", html.escape(db.get("landline", "")))
    h = h.replace("__SITE_URL__", html.escape(db.get("site_url", "") or DEFAULT["site_url"]))
    h = h.replace("__QRV__", hashlib.md5((db.get("qr_b64") or "d").encode()).hexdigest()[:8])
    safe = lambda o: json.dumps(o, ensure_ascii=False).replace("</", "<\\/")
    inject = f"<script>const branches={safe(db['branches'])}; const products={safe(db.get('products', []))}; const mainPhone={safe(main_phone)}; const catalog={safe(db.get('catalog', []))}; const greet={safe(GREETING)};</script>"
    h = h.replace("</head>", inject + "</head>")
    resp = app.response_class(h, mimetype="text/html")
    resp.headers["Cache-Control"] = "no-cache, must-revalidate"   # أي تغيير من الإدارة يظهر للجميع فوراً
    return resp


def _qr_bytes(db):
    data_uri = db.get("qr_b64") or QR_B64 or LOGO_B64
    try:
        return base64.b64decode(data_uri.split(",", 1)[1])
    except Exception:
        return base64.b64decode(QR_B64.split(",", 1)[1])


