    if "user" not in session:
        return redirect("/admin")
    if not can("ads"):
        return "غير مسموح", 403
    f = request.files.get("qr")
    data = f.read(1_500_001) if f else b""
    if not data or len(data) > 1_500_000:
        session["flash"] = "❌ اختر صورة الباركود (حتى 1.5 ميجا)"
        return redirect("/admin/panel")
    if data[:8] != PNG_MAGIC:
        try:
            from PIL import Image
            img = Image.open(io.BytesIO(data)).convert("RGBA")
            buf = io.BytesIO()
            img.save(buf, "PNG")
            data = buf.getvalue()
        except Exception:
            session["flash"] = "❌ ارفع الباركود بصيغة PNG (أو ثبّت Pillow لتحويل JPG/WEBP تلقائياً)"
            return redirect("/admin/panel")
    with DB_LOCK:
        db = load_db()
        db["qr_b64"] = "data:image/png;base64," + base64.b64encode(data).decode()
        save_db(db)
    session["flash"] = "✅ تم رفع الباركود الجديد - ظاهر الآن للجميع"
    return redirect("/admin/panel")

