def my_branches():
    """قائمة الفروع المسموحة للمستخدم الحالي. فاضية = كل الفروع (بدون قيود)."""
    return list(session.get("branches") or [])


def scoped():
    return bool(session.get("branches"))


def branch_ok(name):
    return (not scoped()) or (name in my_branches())


def user_scope(u):
    return list(u.get("branches") or [])


def can_manage_user(u):
    """هل المستخدم الحالي يقدر يعدّل/يحذف هذا المستخدم؟"""
    if not scoped():
        return True
    sc = user_scope(u)
    # المقيَّد بفروع يدير فقط من هم مقيَّدون داخل فروعه (ما يقدر يلمس مستخدم له كل الفروع)
    return bool(sc) and set(sc) <= set(my_branches())


@app.before_request
def refresh_session_perms():
    """تحديث صلاحيات الجلسة من قاعدة البيانات في كل طلب: أي تغيير في الصلاحيات أو الفروع يسري فوراً،
    ولو انحذف المستخدم تنتهي جلسته."""
    if request.path.startswith("/admin") and "user" in session and request.path != "/admin":
        db = load_db()
        me = next((u for u in db["users"] if u.get("name") == session.get("user")), None)
        if me is None:
            session.clear()
            return redirect("/admin")
        session["perms"] = me.get("perms", [])
        names = {b["name"] for b in db["branches"]}
        session["branches"] = [b for b in user_scope(me) if b in names] if user_scope(me) else []
        # لو كل الفروع المخصصة له انحذفت لا نفتح له كل الفروع بالغلط
        if user_scope(me) and not session["branches"]:
            session["branches"] = ["__none__"]


