def send_whatsapp_api(phones, text):
    """إرسال تلقائي حقيقي عبر WhatsApp Cloud API لو تم ضبط WA_TOKEN و WA_PHONE_ID في Render.
    بدونهم يرجع 0 ويستخدم الموقع أزرار واتساب للعميل."""
    token, pid = os.environ.get("WA_TOKEN"), os.environ.get("WA_PHONE_ID")
    if not (token and pid and phones):
        return 0
    import urllib.request
    ok = 0
    for ph in phones:
        try:
            body = json.dumps({"messaging_product": "whatsapp", "to": ph, "type": "text", "text": {"body": text}}).encode()
            rq = urllib.request.Request(f"https://graph.facebook.com/v19.0/{pid}/messages", data=body,
                                        headers={"Authorization": "Bearer " + token, "Content-Type": "application/json"})
            urllib.request.urlopen(rq, timeout=8).read()
            ok += 1
        except Exception:
            pass
    return ok


