@app.route("/api/upload", methods=["POST"])
def api_upload():
    """يستقبل صورة قطعة أو تسجيل صوتي من العميل ويرجع رابطاً يوضع داخل رسالة الواتساب."""
    ip = (request.headers.get("X-Forwarded-For", "") or request.remote_addr or "").split(",")[0].strip()
    if not _up_rate_ok(ip):
        return jsonify({"ok": False, "err": "too_many"}), 429
    f = request.files.get("file")
    data = f.read(UP_MAX_BYTES + 1) if f else b""
    if not data or len(data) > UP_MAX_BYTES:
        return jsonify({"ok": False, "err": "size"}), 400
    ext = None
    if (f.mimetype or "").startswith("image/"):
        try:
            from PIL import Image, ImageOps
            img = ImageOps.exif_transpose(Image.open(io.BytesIO(data))).convert("RGB")
            img.thumbnail((1600, 1600))
            buf = io.BytesIO()
            img.save(buf, "JPEG", quality=85)
            data, ext = buf.getvalue(), "jpg"
        except Exception:
            return jsonify({"ok": False, "err": "image"}), 400
    else:
        ext = _sniff_audio(data[:16])
    if not ext:
        return jsonify({"ok": False, "err": "type"}), 400
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    name = secrets.token_hex(12) + "." + ext
    with open(os.path.join(UPLOAD_DIR, name), "wb") as fh:
        fh.write(data)
    if random.random() < 0.05:
        _prune_uploads()
    return jsonify({"ok": True, "url": "/u/" + name})


@app.route("/u/<name>")
def serve_upload(name):
    m = UP_RE.match(name)
    p = os.path.join(UPLOAD_DIR, name)
    if not m or not os.path.isfile(p):
        return "غير موجود", 404
    resp = send_file(p, mimetype=UP_MIME[m.group(1)], conditional=True)
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["Cache-Control"] = "public, max-age=86400"
    return resp


@app.route("/api/track", methods=["POST"])
def api_track():
    """يسجل أي نقرة للعميل (واتساب/اتصال/موقع/...) على مستوى كل فرع"""
    data = request.get_json(silent=True, force=True) or {}
    t = str(data.get("t", ""))[:30]
    if t not in CLICK_LABELS:
        return jsonify({"ok": False}), 400
    branch = str(data.get("branch", ""))[:80]
    src = str(data.get("src", ""))[:80]
    now = now_sa().strftime("%Y-%m-%d %H:%M:%S")
    with DB_LOCK:
        db = load_db()
        if branch and branch not in {b["name"] for b in db["branches"]}:
            branch = ""
        key = branch or SITE_KEY
        ent = db["clicks"].setdefault(key, {}).setdefault(t, {"count": 0, "last": "", "src": {}})
        ent["count"] += 1
        ent["last"] = now
        if src:
            srcs = ent.setdefault("src", {})
            if src in srcs or len(srcs) < 60:
                srcs[src] = srcs.get(src, 0) + 1
        db["click_log"].append({"time": now, "t": t, "branch": branch, "src": src})
        if len(db["click_log"]) > MAX_LOG:
            db["click_log"] = db["click_log"][-MAX_LOG:]
        save_db(db)
    return jsonify({"ok": True})


