#  إحداثيات الفروع (من روابط الخرائط) + مراكز المدن كاحتياط
# =====================================================================
CITY_CENTERS = {
    "بريدة": (26.326, 43.975), "الزلفى": (26.299, 44.815), "الرس": (25.869, 43.498), "عنيزة": (26.089, 43.993),
    "حفر الباطن": (28.432, 45.964), "حائل": (27.523, 41.697), "المدينة المنورة": (24.467, 39.611),
    "جدة": (21.543, 39.173), "المجمعة": (25.905, 45.346), "مكة المكرمة": (21.389, 39.858), "مكة": (21.389, 39.858),
    "الجوف": (29.970, 40.206), "سكاكا": (29.970, 40.206), "الطائف": (21.270, 40.416), "تبوك": (28.384, 36.555),
    "محايل عسير": (18.540, 42.049), "خميس مشيط": (18.306, 42.729), "الرياض": (24.713, 46.675),
}
CITY_FIX = {"خمبس مشيط": "خميس مشيط", "المدينه المنوره": "المدينة المنورة"}
_COORD_PATTERNS = [
    r"!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)",
    r"@(-?\d+\.\d+),(-?\d+\.\d+)",
    r"[?&](?:q|ll|query|destination|center)=(-?\d+\.\d+)(?:,|%2C)\s*(-?\d+\.\d+)",
    r"^\s*(-?\d+\.\d+)\s*[,،]\s*(-?\d+\.\d+)\s*$",
]


def clean_text(s):
    return " ".join(str(s if s is not None else "").replace("‏", "").replace("‎", "").split())


def fix_city(c):
    c = clean_text(c)
    return CITY_FIX.get(c, c)


def coords_from_text(s):
    import re
    s = urllib.parse.unquote(str(s or ""))
    for pat in _COORD_PATTERNS:
        m = re.search(pat, s)
        if m:
            lat, lng = float(m.group(1)), float(m.group(2))
            if 15 <= lat <= 33 and 34 <= lng <= 56:      # داخل حدود السعودية فقط
                return lat, lng
    return None


def resolve_coords(url, timeout=5):
    """يستخرج الإحداثيات من رابط الموقع (يفك الروابط المختصرة maps.app.goo.gl عبر الإنترنت)."""
    url = str(url or "").strip()
    if not url:
        return None
    c = coords_from_text(url)
    if c or not url.startswith("http"):
        return c
    try:
        import urllib.request
        rq = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120 Safari/537.36",
                                                  "Accept-Language": "ar,en;q=0.8"})
        with urllib.request.urlopen(rq, timeout=timeout) as resp:
            c = coords_from_text(resp.geturl())
            if c:
                return c
            return coords_from_text(resp.read(400000).decode("utf-8", "ignore"))
    except Exception:
        return None


def fill_coords(branches):
    """يحدّث lat/lng من رابط الموقع لكل فرع في القائمة (بالتوازي). يرجع عدد الفروع اللي اتحدّثت فعلاً."""
    from concurrent.futures import ThreadPoolExecutor
    todo = [b for b in branches if b.get("loc")]
    if not todo:
        return 0
    with ThreadPoolExecutor(max_workers=12) as ex:
        results = list(ex.map(lambda b: resolve_coords(b.get("loc")), todo))
    exact = 0
    for b, r in zip(todo, results):
        if r:
            b["lat"], b["lng"] = round(r[0], 6), round(r[1], 6)
            exact += 1
    return exact


