def _xl_style(ws, widths):
    from openpyxl.styles import Font, PatternFill, Alignment
    ws.sheet_view.rightToLeft = True
    for c in ws[1]:
        c.font = Font(bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor="111111")
        c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
    for i, w in enumerate(widths, 1):
        ws.column_dimensions[ws.cell(row=1, column=i).column_letter].width = w
    ws.freeze_panes = "A2"


def _xl_row(ws, values, text_cols=()):
    ws.append(values)
    row = ws[ws.max_row]
    for i, c in enumerate(row):
        if isinstance(c.value, str):
            c.data_type = "s"          # يمنع تحويل النص اللي يبدأ بـ = إلى معادلة
        if i in text_cols:
            c.number_format = "@"


def next_serial(db, date_key):
    cnt = db.setdefault("export_counter", {})
    cnt[date_key] = cnt.get(date_key, 0) + 1
    for k in sorted(cnt)[:-60]:
        cnt.pop(k, None)
    return cnt[date_key]


