def _cell_text(v):
    if v is None:
        return ""
    if isinstance(v, float) and v.is_integer():
        v = int(v)
    return clean_text(v)


def _cell_float(v, default):
    try:
        return float(str(v).replace(",", ".").strip())
    except (TypeError, ValueError):
        return default


def _hnorm(s):
    return clean_text(s).lower()


def _find_table(wb, aliases, key, prefer=()):
    """يدور على الورقة والصف اللي فيهم عناوين الأعمدة (لا يهم اسم الورقة ولا ترتيب الأعمدة).
    يرجع (rows, idx) أو None"""
    names = list(prefer) + [n for n in wb.sheetnames if n not in prefer]
    key_alias = {_hnorm(a) for a in aliases[key]}
    for sn in names:
        if sn not in wb.sheetnames:
            continue
        rows = list(wb[sn].iter_rows(values_only=True))
        for hi, hrow in enumerate(rows[:6]):
            heads = [_hnorm(h) for h in hrow]
            if not (key_alias & set(heads)):
                continue
            idx = {}
            for k, als in aliases.items():
                for a in als:
                    if _hnorm(a) in heads:
                        idx[k] = heads.index(_hnorm(a))
                        break
            out = []
            for r in rows[hi + 1:]:
                if r is None or all(_cell_text(c) == "" for c in r):
                    continue
                out.append({k: (r[i] if i < len(r) else None) for k, i in idx.items()})
            return out, idx
    return None


def backup_db(db):
    os.makedirs("backups", exist_ok=True)
    today = now_sa().strftime("%Y-%m-%d")
    n = len([x for x in os.listdir("backups") if x.startswith(f"alqarawi_db_{today}_")]) + 1
    path = os.path.join("backups", f"alqarawi_db_{today}_{n:03d}.json")
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(db, fh, ensure_ascii=False)
    for old in sorted(os.listdir("backups"))[:-30]:
        try:
            os.remove(os.path.join("backups", old))
        except OSError:
            pass
    return path


def _http_url(v):
    v = clean_text(v)
    return v if v.startswith(("http://", "https://")) else ""


@app.route("/admin/import", methods=["POST"])
def admin_import():
    if "user" not in session:
        return redirect("/admin")
    if not can("branches") or scoped():
        return "غير مسموح", 403
    try:
        from openpyxl import load_workbook
    except ImportError:
        session["flash"] = "❌ مكتبة openpyxl غير مثبتة - أضفها في requirements.txt"
        return redirect("/admin/panel")
    file = request.files.get("xlsx")
    if not file or not file.filename.lower().endswith(".xlsx"):
        session["flash"] = "❌ اختر ملف Excel بصيغة .xlsx"
        return redirect("/admin/panel")
    replace_mode = request.form.get("mode") == "replace"
    try:
        wb = load_workbook(io.BytesIO(file.read()), data_only=True)
    except Exception:
        session["flash"] = "❌ تعذر قراءة الملف - تأكد أنه ملف Excel سليم"
        return redirect("/admin/panel")

    tb = _find_table(wb, BRANCH_ALIASES, "name", prefer=("الفروع", "فروع القرعاوي"))
    ta = _find_table(wb, AD_ALIASES, "title", prefer=("الإعلانات",))
    if not tb and not ta:
        session["flash"] = "❌ لم أجد جدول الفروع - لازم يكون فيه عمود اسمه «اسم الفرع»"
        return redirect("/admin/panel")

    with DB_LOCK:
        db = load_db()
        backup_db(db)
        msgs = []

        if tb:
            rows, idx = tb
            existing = {clean_text(b["name"]): b for b in db["branches"]}
            result, added, updated, seen = [], 0, 0, set()
            need_geo = []
            explicit_ids = set()
            for r in rows:
                name = clean_text(_cell_text(r.get("name")))
                if not name or name in seen:
                    continue
                seen.add(name)
                old = existing.get(name)
                b = dict(old) if old else {
                    "name": name, "city": "بريدة", "phone": "966536405559", "loc": "", "img": "",
                    "hours1": "من 8 صباحا إلى آذان الظهر", "hours2": "من بعد آذان العصر بنصف ساعة إلى آذان العشاء",
                    "friday": "", "lat": None, "lng": None,
                }
                b["name"] = name
                if "city" in r and _cell_text(r["city"]):
                    b["city"] = fix_city(r["city"])
                if "phone" in r and normalize_phone(_cell_text(r["phone"])):
                    b["phone"] = normalize_phone(_cell_text(r["phone"]))
                if "loc" in r and _cell_text(r["loc"]):
                    if _cell_text(r["loc"]) != b.get("loc"):
                        need_geo.append(b)
                    b["loc"] = _cell_text(r["loc"])
                elif not old:
                    need_geo.append(b)
                if "img" in r and _cell_text(r["img"]):
                    b["img"] = _http_url(r["img"])
                for k in ("hours1", "hours2", "friday"):      # الملف هو المرجع: الخلية الفاضية = بدون دوام/استثناء
                    if k in idx:
                        b[k] = _cell_text(r.get(k))
                explicit = "lat" in r and "lng" in r and _cell_text(r["lat"]) and _cell_text(r["lng"])
                if explicit:
                    b["lat"], b["lng"] = _cell_float(r["lat"], b.get("lat")), _cell_float(r["lng"], b.get("lng"))
                    explicit_ids.add(id(b))
                if old:
                    updated += 1
                else:
                    added += 1
                result.append(b)
            if not result:
                session["flash"] = "❌ جدول الفروع فارغ - لم يتم تغيير أي شيء"
                return redirect("/admin/panel")
            # إحداثيات: من روابط الخرائط لو الرابط جديد/متغير، وإلا مركز المدينة للفرع الجديد
            need_geo = [x for x in result if x.get("loc") and id(x) not in explicit_ids]
            exact = fill_coords(need_geo)
            approx = 0
            for b in result:
                if not (b.get("lat") and b.get("lng")):
                    cc = CITY_CENTERS.get(fix_city(b.get("city")), (24.713, 46.675))
                    b["lat"], b["lng"] = cc
                    approx += 1
            if replace_mode:
                removed = len([n for n in existing if n not in seen])
                db["branches"] = result
                msgs.append(f"الفروع: {added} جديد، {updated} محدّث، {removed} محذوف")
            else:
                by_name = {b["name"]: b for b in result}
                db["branches"] = [by_name.get(clean_text(b["name"]), b) for b in db["branches"]] + \
                                 [b for b in result if b["name"] not in existing]
                msgs.append(f"الفروع: {added} جديد، {updated} محدّث")
            msgs.append(f"الإحداثيات: {exact} من روابط الخرائط، {approx} تقريبية من المدينة")

        if ta:
            rows, idx = ta
            existing = {p["title"]: p for p in db.get("products", [])}
            result, added, updated, seen = [], 0, 0, set()
            for r in rows:
                title = _cell_text(r.get("title"))
                if not title or title in seen:
                    continue
                seen.add(title)
                old = existing.get(title)
                p = dict(old) if old else {"title": title, "desc": "", "date": now_sa().strftime("%Y-%m-%d %H:%M")}
                if "desc" in r:
                    p["desc"] = _cell_text(r["desc"])
                if "date" in r and _cell_text(r["date"]) != "":
                    d = r["date"]
                    p["date"] = d.strftime("%Y-%m-%d %H:%M") if hasattr(d, "strftime") else _cell_text(d)
                updated += 1 if old else 0
                added += 0 if old else 1
                result.append(p)
            if replace_mode and result:
                removed = len([t for t in existing if t not in seen])
                db["products"] = result
                msgs.append(f"الإعلانات: {added} جديد، {updated} محدّث، {removed} محذوف")
            elif not replace_mode and result:
                by_title = {p["title"]: p for p in result}
                db["products"] = [by_title.get(p["title"], p) for p in db.get("products", [])] + \
                                 [p for p in result if p["title"] not in existing]
                msgs.append(f"الإعلانات: {added} جديد، {updated} محدّث")
        save_db(db)
    session["flash"] = "✅ تم الاستيراد (" + ("استبدال كامل" if replace_mode else "دمج") + ") - " + " | ".join(msgs) + \
                       " - تم حفظ نسخة احتياطية قبل الاستيراد، والتسلسل أُعيد ترتيبه حسب الملف"
    return redirect("/admin/panel")


@app.errorhandler(413)
def too_large(_):
    if request.path.startswith("/api/"):
        return jsonify({"ok": False, "err": "size"}), 413
    session["flash"] = "❌ الملف أكبر من 5 ميجا"
    return redirect("/admin/panel")


