def deny(msg="❌ ليس لديك صلاحية لهذا الإجراء"):
    session["flash"] = msg
    return redirect("/admin/panel")


def _read_scope(f, mode_key, br_key, db):
    """يقرأ نطاق الفروع من الفورم. يرجع [] = كل الفروع، قائمة = فروع محددة، None = اختيار غير صالح."""
    existing = {b["name"] for b in db["branches"]}
    chosen = [n for n in f.getlist(br_key) if n in existing]
    if scoped():                      # المقيَّد بفروع لا يعطي إلا من فروعه
        chosen = [n for n in chosen if n in my_branches()]
        return chosen or None
    if f.get(mode_key, "all") == "selected":
        return chosen or None
    return []


def panel_post():
    db = load_db()
    f = request.form
    if "save_marquee" in f:
        if not can("marquee"):
            return deny()
        txt = f.get("marquee_text", "").strip()
        if txt:
            db["marquee_text"] = txt
        save_db(db)
    elif "save_phones" in f:
        if not can("phones"):
            return deny()
        old_main = db.get("main_phone", "")
        main = normalize_phone(f.get("main_phone", "")) or old_main
        db["main_phone"] = main
        db["landline"] = normalize_phone(f.get("landline", "")) or db.get("landline", "")
        phones = []
        for line in f.get("notify_phones_text", "").splitlines():
            for part in line.split(","):
                pp = normalize_phone(part.strip())
                if pp and pp not in phones:
                    phones.append(pp)
        # لو الرقم القديم كان في قائمة التنبيهات نستبدله بالجديد
        if old_main and old_main != main and old_main in phones:
            phones = [main if p == old_main else p for p in phones]
            phones = list(dict.fromkeys(phones))
        if main and main not in phones:
            phones = [main] + phones
        db["notify_phones"] = phones or [main]
        save_db(db)
        session["flash"] = "✅ تم حفظ الأرقام - جوال خدمة العملاء الجديد ظاهر الآن في كل الأزرار والنصوص (بدون تأثير على واتس الفروع)"
    elif "add_branch" in f:
        if not can("add"):
            return deny()
        if scoped():
            return deny("❌ حسابك مقيَّد بفروع محددة - لا يمكنك إضافة فرع جديد")
        name = clean_text(f.get("branch_name", ""))
        if name:
            nb = {
                "name": name, "city": fix_city(f.get("branch_city", "")) or "بريدة",
                "phone": normalize_phone(f.get("branch_phone", "")) or "966536405559",
                "loc": f.get("branch_loc", "").strip(), "img": _http_url(f.get("branch_img", "")),
                "hours1": f.get("branch_h1", "").strip() or "من 8 صباحا إلى آذان الظهر",
                "hours2": f.get("branch_h2", "").strip() or "من بعد آذان العصر بنصف ساعة إلى آذان العشاء",
                "friday": f.get("branch_fri", "").strip(),
                "lat": _cell_float(f.get("branch_lat", ""), None), "lng": _cell_float(f.get("branch_lng", ""), None),
            }
            if nb["lat"] is None or nb["lng"] is None:
                nb["lat"] = nb["lng"] = None
                fill_coords([nb])
                if nb["lat"] is None:
                    nb["lat"], nb["lng"] = CITY_CENTERS.get(nb["city"], (24.713, 46.675))
                    session["flash"] = "⚠️ تمت إضافة الفرع بإحداثيات تقريبية من المدينة (لم أستطع قراءتها من الرابط) - عدّلها يدوياً لدقة «أقرب فرع»"
            db["branches"].append(nb)
            save_db(db)
    elif "edit_branch" in f:
        idx = to_int(f.get("edit_branch"))
        if 0 <= idx < len(db["branches"]):
            b = db["branches"][idx]
            if not branch_ok(b["name"]):
                return deny("❌ هذا الفرع ليس ضمن الفروع المسموحة لك")
            if can("branches"):
                old_name, old_loc, old_lat, old_lng = b["name"], b.get("loc", ""), b.get("lat"), b.get("lng")
                b["name"] = clean_text(f.get(f"edit_name_{idx}", b["name"])) or b["name"]
                b["city"] = fix_city(f.get(f"edit_city_{idx}", b["city"])) or b["city"]
                b["phone"] = normalize_phone(f.get(f"edit_phone_{idx}", b["phone"])) or b["phone"]
                b["loc"] = f.get(f"edit_loc_{idx}", b["loc"]).strip()
                b["img"] = _http_url(f.get(f"edit_img_{idx}", b.get("img", "")))
                b["hours1"] = f.get(f"edit_h1_{idx}", b["hours1"]).strip()
                b["hours2"] = f.get(f"edit_h2_{idx}", b["hours2"]).strip()
                b["friday"] = f.get(f"edit_fri_{idx}", b.get("friday", "")).strip()
                b["lat"] = _cell_float(f.get(f"edit_lat_{idx}"), b["lat"])
                b["lng"] = _cell_float(f.get(f"edit_lng_{idx}"), b["lng"])
                if b["loc"] != old_loc and b["lat"] == old_lat and b["lng"] == old_lng:
                    fill_coords([b])                      # تغيّر الرابط ولم يتغير الإحداثي: نقرأه من الرابط الجديد
                if b["name"] != old_name:          # نحافظ على التقييمات والنقرات والمستخدمين عند تغيير اسم الفرع
                    for r in db.get("reviews", []):
                        if r.get("branch") == old_name:
                            r["branch"] = b["name"]
                    if old_name in db["clicks"] and b["name"] not in db["clicks"]:
                        db["clicks"][b["name"]] = db["clicks"].pop(old_name)
                    for u in db["users"]:
                        if old_name in (u.get("branches") or []):
                            u["branches"] = [b["name"] if x == old_name else x for x in u["branches"]]
                save_db(db)
            elif can("hours"):                         # صلاحية الدوام فقط: يعدّل الأوقات ولا شيء غيرها
                b["hours1"] = f.get(f"edit_h1_{idx}", b["hours1"]).strip()
                b["hours2"] = f.get(f"edit_h2_{idx}", b["hours2"]).strip()
                b["friday"] = f.get(f"edit_fri_{idx}", b.get("friday", "")).strip()
                save_db(db)
            else:
                return deny()
    elif "geocode_all" in f:
        if not can("branches"):
            return deny()
        n = fill_coords([b for b in db["branches"] if branch_ok(b["name"])])
        save_db(db)
        session["flash"] = (f"✅ تم تحديث إحداثيات {n} فرع من روابط الخرائط" if n else
                            "⚠️ لم أستطع قراءة الإحداثيات من الروابط (الإنترنت أو الروابط المختصرة) - اكتب lat/lng يدوياً أو ضع رابطاً كاملاً فيه @lat,lng")
    elif "delete_branch" in f:
        if not can("branches"):
            return deny()
        idx = to_int(f.get("delete_branch"))
        if 0 <= idx < len(db["branches"]):
            if not branch_ok(db["branches"][idx]["name"]):
                return deny("❌ هذا الفرع ليس ضمن الفروع المسموحة لك")
            db["branches"].pop(idx)
            save_db(db)
    elif "add_ad" in f:
        if not can("ads"):
            return deny()
        title = f.get("ad_title", "").strip()
        if title:
            db.setdefault("products", []).append({
                "title": title, "desc": f.get("ad_desc", ""),
                "date": now_sa().strftime("%Y-%m-%d %H:%M"),
            })
            save_db(db)
    elif "edit_ad" in f:
        if not can("ads"):
            return deny()
        idx = to_int(f.get("edit_ad"))
        if 0 <= idx < len(db.get("products", [])):
            p = db["products"][idx]
            p["title"] = f.get(f"edit_ad_title_{idx}", p["title"])
            p["desc"] = f.get(f"edit_ad_desc_{idx}", p.get("desc", ""))
            save_db(db)
    elif "delete_ad" in f:
        if not can("ads"):
            return deny()
        idx = to_int(f.get("delete_ad"))
        if 0 <= idx < len(db.get("products", [])):
            db["products"].pop(idx)
            save_db(db)
    elif "add_product" in f:
        if not can("ads"):
            return deny()
        nm, ar = clean_text(f.get("pr_name", "")), clean_text(f.get("pr_ar", ""))
        if nm or ar:
            db.setdefault("catalog", []).append({"name": nm or ar, "arabic": ar or nm,
                                                 "desc": f.get("pr_desc", "").strip()[:300], "img": _http_url(f.get("pr_img", ""))})
            save_db(db)
            session["flash"] = "✅ تمت إضافة المنتج - ظاهر الآن في الموقع"
    elif "edit_product" in f:
        if not can("ads"):
            return deny()
        idx = to_int(f.get("edit_product"))
        cat = db.setdefault("catalog", [])
        if 0 <= idx < len(cat):
            p = cat[idx]
            p["name"] = clean_text(f.get(f"edit_pr_name_{idx}", p.get("name", ""))) or p.get("name", "")
            p["arabic"] = clean_text(f.get(f"edit_pr_ar_{idx}", p.get("arabic", ""))) or p.get("arabic", "")
            p["desc"] = f.get(f"edit_pr_desc_{idx}", p.get("desc", "")).strip()[:300]
            p["img"] = _http_url(f.get(f"edit_pr_img_{idx}", p.get("img", "")))
            save_db(db)
            session["flash"] = "✅ تم حفظ المنتج"
    elif "move_product" in f:
        if not can("ads"):
            return deny()
        try:
            idx_s, way = f.get("move_product", "").split(":")
            idx = int(idx_s)
        except ValueError:
            idx, way = -1, ""
        cat = db.setdefault("catalog", [])
        j = idx - 1 if way == "up" else idx + 1
        if 0 <= idx < len(cat) and 0 <= j < len(cat):
            cat[idx], cat[j] = cat[j], cat[idx]
            save_db(db)
    elif "delete_product" in f:
        if not can("ads"):
            return deny()
        idx = to_int(f.get("delete_product"))
        cat = db.setdefault("catalog", [])
        if 0 <= idx < len(cat):
            cat.pop(idx)
            save_db(db)
    elif "add_user" in f:
        if not can("users"):
            return deny()
        name = f.get("user_name", "").strip()
        pwd = f.get("user_pass", "").strip()
        if name and pwd:
            if any(u.get("name") == name for u in db["users"]):
                return deny("❌ اسم المستخدم موجود من قبل - اختر اسماً آخر")
            perms = [p for p in f.getlist("user_perms") if p in ALL_PERMS]
            if scoped():
                perms = [p for p in perms if can(p) and p != "add"]     # لا يعطي أكثر من صلاحياته
            if not perms:
                return deny("❌ اختر صلاحية واحدة على الأقل")
            scope = _read_scope(f, "user_mode", "user_branches", db)
            if scope is None:
                return deny("❌ اختر فرعاً واحداً على الأقل للمستخدم (أو «كل الفروع»)")
            db["users"].append({"name": name, "pass": pwd, "perms": perms, "branches": scope})
            save_db(db)
            session["flash"] = "✅ تمت إضافة المستخدم"
    elif "edit_user" in f:
        if not can("users"):
            return deny()
        idx = to_int(f.get("edit_user"))
        if 0 <= idx < len(db["users"]):
            u = db["users"][idx]
            if not can_manage_user(u):
                return deny("❌ لا يمكنك تعديل هذا المستخدم (خارج فروعك)")
            is_self = u.get("name") == session.get("user")
            new_name = f.get(f"edit_user_name_{idx}", u["name"]).strip() or u["name"]
            if new_name != u["name"] and any(x.get("name") == new_name for x in db["users"]):
                return deny("❌ اسم المستخدم موجود من قبل - اختر اسماً آخر")
            if not is_self:
                perms = [p for p in f.getlist(f"edit_user_perms_{idx}") if p in ALL_PERMS]
                if scoped():
                    perms = [p for p in perms if can(p) and p != "add"]
                if not perms:
                    return deny("❌ اختر صلاحية واحدة على الأقل")
                scope = _read_scope(f, f"edit_user_mode_{idx}", f"edit_user_branches_{idx}", db)
                if scope is None:
                    return deny("❌ اختر فرعاً واحداً على الأقل للمستخدم (أو «كل الفروع»)")
                u["perms"] = perms
                u["branches"] = scope
            u["name"] = new_name
            u["pass"] = f.get(f"edit_user_pass_{idx}", u["pass"]).strip() or u["pass"]
            if is_self:
                session["user"] = new_name
            save_db(db)
            session["flash"] = "✅ تم حفظ المستخدم" + (" (صلاحياتك وفروعك لا تتغير من حسابك أنت)" if is_self else "")
    elif "delete_user" in f:
        if not can("users"):
            return deny()
        idx = to_int(f.get("delete_user"))
        if 0 <= idx < len(db["users"]):
            u = db["users"][idx]
            if not can_manage_user(u):
                return deny("❌ لا يمكنك حذف هذا المستخدم (خارج فروعك)")
            if u.get("name") == session.get("user"):
                return deny("❌ لا يمكنك حذف حسابك وأنت داخل به")
            db["users"].pop(idx)
            save_db(db)
    elif "delete_review" in f:
        if not can("reviews"):
            return deny()
        idx = to_int(f.get("delete_review"))
        revs = db.get("reviews", [])
        if 0 <= idx < len(revs):
            if not branch_ok(revs[idx].get("branch", "")):
                return deny("❌ هذا التقييم ليس لأحد فروعك")
            revs.pop(idx)
            save_db(db)
    elif "save_site" in f:
        if not can("ads"):
            return deny()
        db["site_url"] = f.get("site_url", "").strip()[:120]
        save_db(db)
        session["flash"] = "✅ تم حفظ النص تحت الباركود"
    elif "reset_qr" in f:
        if not can("ads"):
            return deny()
        db["qr_b64"] = ""
        save_db(db)
        session["flash"] = "✅ رجع الباركود الأصلي"
    elif "reset_clicks" in f:
        if not can("reviews") or scoped():
            return deny()
        db["clicks"] = {}
        db["click_log"] = []
        save_db(db)
    return redirect("/admin/panel")


@app.route("/admin/panel", methods=["GET", "POST"])
def panel():
    if "user" not in session:
        return redirect("/admin")
    if request.method == "POST":
        with DB_LOCK:
            return panel_post()
    db = load_db()

    def bfield(label, name, value, half=False, hint=""):
        w = "48%" if half else "100%"
        m = "2px 1%" if half else "2px 0"
        return (f"<div style='display:inline-block;width:{w};vertical-align:top;margin:{m}'><label style='font-size:11px;color:#555'>{label}</label>"
                f"<input name='{name}' value='{e(value)}' style='width:100%;padding:6px;border:1px solid #999;border-radius:6px'>"
                f"{('<div style=font-size:10px;color:#999>' + hint + '</div>') if hint else ''}</div>")

    HOURS_HINT = "مثال: من 8 صباحا إلى آذان الظهر  |  من بعد آذان العصر بنصف ساعة إلى 9:30 مساء"

    def branch_form_fields(prefix, v, i=None, hours_only=False):
        n = (lambda k: f"edit_{k}_{i}") if i is not None else (lambda k: f"branch_{k}")
        if hours_only:
            return (bfield("دوام 1 - صباحا", n("h1"), v.get("hours1", ""), hint=HOURS_HINT) +
                    bfield("دوام 2 - مساء", n("h2"), v.get("hours2", "")) +
                    bfield("دوام الجمعة (اتركه فارغاً = مغلق يوم الجمعة)", n("fri"), v.get("friday", "")))
        return (bfield("اسم الفرع", n("name"), v.get("name", "")) + bfield("المدينة", n("city"), v.get("city", "")) +
                bfield("جوال الفرع (واتساب الفرع)", n("phone"), v.get("phone", "")) +
                bfield("رابط الموقع (Google Maps)", n("loc"), v.get("loc", "")) +
                bfield("رابط صورة الفرع (اختياري)", n("img"), v.get("img", "")) +
                bfield("دوام 1 - صباحا", n("h1"), v.get("hours1", ""), hint=HOURS_HINT) +
                bfield("دوام 2 - مساء", n("h2"), v.get("hours2", "")) +
                bfield("دوام الجمعة (اتركه فارغاً = مغلق يوم الجمعة)", n("fri"), v.get("friday", "")) +
                bfield("lat (خط العرض)", n("lat"), v.get("lat", ""), half=True) + bfield("lng (خط الطول)", n("lng"), v.get("lng", ""), half=True))

    hours_only = (not can("branches")) and can("hours")
